-- 094_payment_certification_decisions.sql
BEGIN;
CREATE TABLE IF NOT EXISTS public.project_payment_certification_decisions(
 id uuid PRIMARY KEY,certification_case_id uuid NOT NULL REFERENCES public.project_payment_certification_cases(id)ON DELETE RESTRICT,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,decision_number integer NOT NULL CHECK(decision_number>0),decision_type text NOT NULL CHECK(decision_type IN('FULL','PARTIAL','HELD')),certified_amount numeric(24,2)NOT NULL CHECK(certified_amount>=0),held_amount numeric(24,2)NOT NULL CHECK(held_amount>=0),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),decision_reason text NOT NULL CHECK(btrim(decision_reason)<>''AND char_length(decision_reason)<=3000),evidence_ready_at_decision boolean NOT NULL,decided_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,decided_at timestamptz NOT NULL DEFAULT now(),UNIQUE(certification_case_id,decision_number)
);
CREATE OR REPLACE FUNCTION private.prevent_payment_certification_decision_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'PAYMENT_CERTIFICATION_DECISION_IMMUTABLE'USING ERRCODE='55000';END;$$;
DROP TRIGGER IF EXISTS payment_certification_decision_immutable ON public.project_payment_certification_decisions;CREATE TRIGGER payment_certification_decision_immutable BEFORE UPDATE OR DELETE ON public.project_payment_certification_decisions FOR EACH ROW EXECUTE FUNCTION private.prevent_payment_certification_decision_mutation();
ALTER TABLE public.project_payment_certification_decisions ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS payment_certification_decisions_select ON public.project_payment_certification_decisions;CREATE POLICY payment_certification_decisions_select ON public.project_payment_certification_decisions FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.project_payment_certification_decisions FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_payment_certification_decisions TO authenticated;
CREATE OR REPLACE FUNCTION public.decide_payment_certification(p_certification_case_id uuid,p_decision_id uuid,p_decision_type text,p_certified_amount numeric,p_decision_reason text,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;c public.project_payment_certification_cases%ROWTYPE;e public.project_payment_certification_evidence%ROWTYPE;m public.project_payment_milestones%ROWTYPE;s public.project_payment_schedules%ROWTYPE;req public.write_command_requests%ROWTYPE;kind text:=upper(btrim(COALESCE(p_decision_type,'')));amount numeric:=COALESCE(p_certified_amount,0);decision_no integer;next_status text;held numeric;result jsonb;
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;SELECT *INTO c FROM public.project_payment_certification_cases WHERE id=p_certification_case_id FOR UPDATE;IF c.id IS NULL THEN RAISE EXCEPTION'PAYMENT_CERTIFICATION_CASE_NOT_FOUND'USING ERRCODE='P0002';END IF;SELECT *INTO e FROM public.project_payment_certification_evidence WHERE certification_case_id=c.id;SELECT *INTO m FROM public.project_payment_milestones WHERE id=c.milestone_id FOR UPDATE;SELECT *INTO s FROM public.project_payment_schedules WHERE id=m.payment_schedule_id;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(c.project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_CERTIFICATION_DECISION_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_decision_id IS NULL OR p_client_request_id IS NULL OR kind NOT IN('FULL','PARTIAL','HELD')OR btrim(COALESCE(p_decision_reason,''))=''OR char_length(p_decision_reason)>3000 OR c.status NOT IN('UNDER_CERTIFICATION','HELD')THEN RAISE EXCEPTION'INVALID_CERTIFICATION_DECISION_COMMAND'USING ERRCODE='22023';END IF;IF c.status='HELD'AND kind='HELD'THEN RAISE EXCEPTION'CERTIFICATION_ALREADY_HELD'USING ERRCODE='55000';END IF;IF kind='FULL'AND(e.evidence_ready IS NOT TRUE OR amount<>m.planned_amount)THEN RAISE EXCEPTION'FULL_CERTIFICATION_REQUIRES_READY_EVIDENCE_AND_FULL_AMOUNT'USING ERRCODE='22023';ELSIF kind='PARTIAL'AND(amount<=0 OR amount>=m.planned_amount)THEN RAISE EXCEPTION'PARTIAL_CERTIFICATION_AMOUNT_OUT_OF_RANGE'USING ERRCODE='22023';ELSIF kind='HELD'AND amount<>0 THEN RAISE EXCEPTION'HELD_CERTIFICATION_AMOUNT_MUST_BE_ZERO'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'payment_certification.decide',p_client_request_id,c.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='payment_certification.decide'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;SELECT COALESCE(max(decision_number),0)+1 INTO decision_no FROM public.project_payment_certification_decisions WHERE certification_case_id=c.id;next_status:=CASE kind WHEN'FULL'THEN'APPROVED'WHEN'PARTIAL'THEN'PARTIALLY_APPROVED'ELSE'HELD'END;held:=m.planned_amount-amount;INSERT INTO public.project_payment_certification_decisions VALUES(p_decision_id,c.id,c.project_id,decision_no,kind,amount,held,s.currency_code,btrim(p_decision_reason),e.evidence_ready,u,now());UPDATE public.project_payment_certification_cases SET status=next_status WHERE id=c.id;UPDATE public.project_payment_milestones SET status=CASE WHEN kind IN('FULL','PARTIAL')THEN'APPROVED'ELSE'UNDER_CERTIFICATION'END WHERE id=m.id;result:=jsonb_build_object('decisionId',p_decision_id,'decisionNumber',decision_no,'decisionType',kind,'caseStatus',next_status,'certifiedAmount',amount,'heldAmount',held,'currencyCode',s.currency_code);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_project_payment_certifications(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_CERTIFICATION_FORBIDDEN'USING ERRCODE='42501';END IF;RETURN jsonb_build_object('projectId',p_project_id,'cases',COALESCE((SELECT jsonb_agg(jsonb_build_object('certificationCaseId',c.id,'caseNumber',c.case_number,'status',c.status,'milestoneId',c.milestone_id,'milestoneTitle',m.title,'plannedAmount',m.planned_amount,'currencyCode',s.currency_code,'openedAt',c.opened_at,'evidence',jsonb_build_object('contractMilestoneAmount',e.contract_milestone_amount,'requiredProgress',e.required_progress,'contractorReportedProgress',e.contractor_reported_progress,'pmVerifiedProgress',e.pm_verified_progress,'pmVerifiedAt',e.pm_verified_at,'scheduleProgress',e.schedule_progress,'boqQuantityProgress',e.boq_quantity_progress,'boqQuantityEvidenceAvailable',e.boq_quantity_evidence_available,'openCriticalIssueCount',e.open_critical_issue_count,'openSnagCount',e.open_snag_count,'pendingVariationCount',e.pending_variation_count,'pendingVariationExposure',e.pending_variation_exposure,'documents',e.documents,'evidenceNote',e.evidence_note,'evidenceReady',e.evidence_ready,'capturedAt',e.captured_at),'decisions',COALESCE((SELECT jsonb_agg(jsonb_build_object('decisionId',d.id,'decisionNumber',d.decision_number,'decisionType',d.decision_type,'certifiedAmount',d.certified_amount,'heldAmount',d.held_amount,'decisionReason',d.decision_reason,'evidenceReadyAtDecision',d.evidence_ready_at_decision,'decidedAt',d.decided_at)ORDER BY d.decision_number)FROM public.project_payment_certification_decisions d WHERE d.certification_case_id=c.id),'[]'::jsonb))ORDER BY c.case_number DESC)FROM public.project_payment_certification_cases c JOIN public.project_payment_certification_evidence e ON e.certification_case_id=c.id JOIN public.project_payment_milestones m ON m.id=c.milestone_id JOIN public.project_payment_schedules s ON s.id=m.payment_schedule_id WHERE c.project_id=p_project_id),'[]'::jsonb));END;$$;
REVOKE ALL ON FUNCTION private.prevent_payment_certification_decision_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.decide_payment_certification(uuid,uuid,text,numeric,text,uuid),public.get_project_payment_certifications(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.decide_payment_certification(uuid,uuid,text,numeric,text,uuid),public.get_project_payment_certifications(bigint)TO authenticated;
COMMIT;
